//! Control Theory Formula Engine
use serde::{Deserialize, Serialize};
use std::f32::consts::PI;
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct TransferFunction { pub num: Vec<f32>, pub den: Vec<f32> }
impl TransferFunction { pub fn new(num: Vec<f32>, den: Vec<f32>)->Self{ assert!(!den.is_empty()); Self{num, den} } pub fn first_order(k:f32,tau:f32)->Self{ Self::new(vec![k], vec![tau,1.0]) } pub fn bode(&self, w:f32)->(f32,f32){ let (rn, inn)=Self::poly_jw(&self.num,w); let (rd, imd)=Self::poly_jw(&self.den,w); let mag=(rn*rn+inn*inn).sqrt()/(rd*rd+imd*imd).sqrt().max(1e-9); (20.0*mag.log10().max(-120.0), (inn.atan2(rn)-imd.atan2(rd))*180.0/PI) } fn poly_jw(c:&[f32], w:f32)->(f32,f32){ let mut re=0.0; let mut im=0.0; let n=c.len(); for i in 0..n{ let power=n-1-i; let (pr,pi)=Self::j_pow(power,w); re+=c[i]*pr; im+=c[i]*pi; } (re,im) } fn j_pow(k:usize,w:f32)->(f32,f32){ let wk=w.powi(k as i32); match k%4{0=>(wk,0.0),1=>(0.0,wk),2=>(-wk,0.0),3=>(0.0,-wk),_=>unreachable!()} } pub fn step_response(&self, t_final:f32, dt:f32)->Vec<f32>{ let n=self.den.len()-1; if n==0{return vec![0.0];} let a0=self.den[0]; let den_n:Vec<f32>=self.den.iter().map(|c| c/a0).collect(); let num_n:Vec<f32>=self.num.iter().map(|c| c/a0).collect(); let steps=(t_final/dt) as usize; let mut x=vec![0.0;n]; let mut y_hist=Vec::with_capacity(steps); let u=1.0; for _ in 0..steps{ let mut x_dot=vec![0.0;n]; for i in 0..n-1{ x_dot[i]=x[i+1]; } let mut last=-den_n[n]*x[0]; for i in 1..n{ last-=den_n[n-i]*x[i]; } last+=u; x_dot[n-1]=last; for i in 0..n{ x[i]+=x_dot[i]*dt; } let mut y=0.0; for i in 0..n.min(num_n.len()){ y+=num_n[num_n.len()-1-i]*x[i]; } if num_n.len()>n{ y+=num_n[0]*u; } y_hist.push(y); } y_hist } }
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct StateSpace { pub a: Vec<Vec<f32>>, pub b: Vec<Vec<f32>>, pub c: Vec<Vec<f32>>, pub d: Vec<Vec<f32>>, pub n:usize, pub m:usize, pub p:usize }
impl StateSpace { pub fn new(a:Vec<Vec<f32>>, b:Vec<Vec<f32>>, c:Vec<Vec<f32>>, d:Vec<Vec<f32>>)->Self{ let n=a.len(); let m=b.get(0).map(|r| r.len()).unwrap_or(0); let p=c.len(); Self{a,b,c,d,n,m,p} } pub fn step(&self, x:&mut [f32], u:&[f32], dt:f32)->Vec<f32>{ let mut x_dot=vec![0.0;self.n]; for i in 0..self.n{ let mut sum=0.0; for j in 0..self.n{ sum+=self.a[i][j]*x[j]; } for j in 0..self.m{ sum+=self.b[i][j]*u[j]; } x_dot[i]=sum; } for i in 0..self.n{ x[i]+=x_dot[i]*dt; } let mut y=vec![0.0;self.p]; for i in 0..self.p{ let mut sum=0.0; for j in 0..self.n{ sum+=self.c[i][j]*x[j]; } for j in 0..self.m{ sum+=self.d[i][j]*u[j]; } y[i]=sum; } y } pub fn from_first_order_tf(k:f32,tau:f32)->Self{ Self::new(vec![vec![-1.0/tau]], vec![vec![k/tau]], vec![vec![1.0]], vec![vec![0.0]]) } }
pub struct StabilityAnalyzer;
impl StabilityAnalyzer { pub fn is_stable_den(den:&[f32])->bool{ if den.is_empty()||den[0]<=0.0{return false;} let n=den.len()-1; if n==0{return true;} let mut routh:Vec<Vec<f32>>=vec![Vec::new(),Vec::new()]; for (i,&c) in den.iter().enumerate(){ if i%2==0{routh[0].push(c);}else{routh[1].push(c);} } let max_len=routh[0].len().max(routh[1].len()); for r in &mut routh{ while r.len()<max_len{ r.push(0.0);} } for r in 2..=n{ let mut next=vec![0.0;max_len]; for c in 0..max_len-1{ let a=routh[r-2][0]; let b=routh[r-1][0]; if b.abs()<1e-9{return false;} let a_next=*routh[r-2].get(c+1).unwrap_or(&0.0); let b_next=*routh[r-1].get(c+1).unwrap_or(&0.0); next[c]=(b*a_next-a*b_next)/b; } if next[0]<=1e-9{return false;} routh.push(next); } true } pub fn gain_margin(tf:&TransferFunction)->f32{ let mut gm=f32::INFINITY; for i in 0..1000{ let w=0.1*(1.05f32).powi(i); let (mag_db,phase)=tf.bode(w); if phase < -179.0 && phase > -181.0{ gm=-mag_db; break; } } gm } pub fn phase_margin(tf:&TransferFunction)->f32{ let mut pm=f32::INFINITY; for i in 0..1000{ let w=0.1*(1.05f32).powi(i); let (mag_db,phase)=tf.bode(w); if mag_db.abs()<0.5{ pm=180.0+phase; break; } } pm } }
pub fn ziegler_nichols_pi(ku:f32, pu:f32)->(f32,f32){ (0.45*ku, 0.54*ku/pu) }
pub fn ziegler_nichols_pid(ku:f32, pu:f32)->(f32,f32,f32){ (0.6*ku, 1.2*ku/pu, 0.075*ku*pu) }
